from pathlib import Path
import json,re,hashlib
root=Path('literature-reading/Regulating-Conglomerates');p=root/'src/reader.json';s=json.loads(p.read_text());before=json.loads(p.read_text())
Path('.work/reader-before-concision.json').write_text(p.read_text())
Path('.work/deck-preserved.sha256').write_text(hashlib.sha256((root/'presentation.html').read_bytes()).hexdigest())
def setbody(n,b):s[n-1]['body']=b
def replace(n,a,b=''):
 assert a in s[n-1]['body'],(n,a[:60]);s[n-1]['body']=s[n-1]['body'].replace(a,b)
def droplast(n):
 b=s[n-1]['body'];matches=list(re.finditer(r'<p(?: [^>]*)?>.*?</p>',b,re.S));m=matches[-1];assert m.end()==len(b),n;s[n-1]['body']=b[:m.start()]
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+v+'</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in r)+'</tr>' for r in rows)+'</tbody></table>'
def figure(n):return re.search(r'<figure.*?</figure>',s[n-1]['body'],re.S).group()
s[1].update(title='千家企业节能行动：政策要求企业做什么？',sub='先了解政策的对象与执行方式，再看关联企业可能产生的反应',source='原文 Section I.A（政策背景）、Section III（关联企业反应）')
setbody(2,'<p>2006 年，中国启动千家企业节能行动，将一批高耗能企业列入名单，并向企业分解节能目标。政策希望减少能源消耗、提高能源利用效率。</p>'+table(['政策要素','具体含义'],[['监管对象','名单内的企业承担节能任务；同一集团的其他企业可能没有被列入名单。具体名单按历史能耗确定。'],['执行方式','地方负责落实、监测与考核。论文的制度调查发现，实际执行较多依赖可监测的企业能耗配额。'],['企业怎样响应','企业可以改进技术、用更少能源生产相同产品，也可能通过减少生产来降低能耗。']])+'<h3>政策要求企业 A 减少能耗，企业 B 的能耗会发生什么样的变化？</h3><p>假设 A、B 同属一个集团，生产相近产品，只有 A 被列入名单。如果集团把 A 的部分生产任务交给 B，B 的产出和能耗就可能增加。</p><p class="takeaway">论文考察：关联企业是否承接了生产？把名单外企业的变化也计入后，整个行业实际节约了多少能源？</p>')
s[2]['sub']='同属一个集团的 A、B 生产相近产品；以下假设数字用于说明生产转移'
droplast(3)
replace(3,'<p class="caption">关联企业的能耗增加抵消了部分直接节能</p>','<p class="caption">集团通过所有权关系连接多家企业，可以统筹生产。例中的 B 是 A 的关联企业；数字仅用于说明机制，并非论文估计结果。</p>')
