setbody(5,table(['时间','政策进程','在研究中的用途'],[['2004','决定名单所用的历史能耗年份','名单依据历史能耗确定；模型也主要匹配这一年的企业分布。'],['2006','4 月公布千家企业节能行动','事件研究将这一年作为比较基准；平均效应回归仍把它归入政策前时期。'],['2007–2010/11','千家企业行动考核实施与政策运行','2007 年及以后记为政策后时期（Post=1），分析终点随数据来源而异。'],['2011 年末公布，随后实施','万家企业节能低碳行动扩大覆盖范围','后来入选、此前未被千家行动直接监管的企业可作对照；比较窗口止于扩大监管之前。']]))
setbody(6,table(['概念','含义','本文的度量与解释'],[['能耗 E','生产一共用了多少能源','CESD 主要记录煤、油、气等一次能源。能耗减少可以来自少生产，也可以来自单位产品用能减少。'],['产出 Y','生产活动规模有多大','实证主要使用产值／收入；模型中的 q 对应物理产量，二者度量口径不同。'],['能源效率 Y/E','每单位能源对应多少产值','产值除以能耗；除技术外，也受价格与产品结构影响。产出和能耗同比例下降时，该比值不变。'],['能源强度 E/Y','每单位产值需要多少能源','能耗除以产值，是能源效率的倒数。强度下降表示每单位产值用能减少。']])+'<div class="equation">示例：产值 100 → 80 万元，能耗 50 → 40 吨标准煤<br>能源效率：100/50 = 80/40 = 2 万元／吨标准煤</div>')
replace(7,'<p>能源效率为 Y/E，能源强度为 E/Y。宏观政策通常以 GDP 为分母，企业分析则使用产值或实物产量；相同指标名称在不同统计层级下对应的度量口径有所不同。</p>','<p class="caption">分母 Y 随统计层级而异：宏观政策通常使用 GDP，企业分析则采用产值或实物产量。</p>')
setbody(8,table(['环节','政策如何执行','对企业行为的影响'],[['中央设定目标','通过节能目标推动技术和效率改善','企业面对减少能源消耗、提高能源利用效率的要求。'],['地方落实与考核','产品和工艺复杂，节能量的基准、产品结构及核算方式难以统一核验','地方较多依赖可监测的企业能耗配额；配额可包含预期增长空间。'],['约束落到企业','考核与地方官员激励相连，超额企业可能面临限电或停产','企业可通过减少生产达标，也可改进技术；不同方式对产出与能效的影响不同。']]))
setbody(9,table(['数据','提供什么','在研究里解决什么问题'],[['CESD<br>中国环境统计数据库','企业产值及煤、油、气等一次能源使用，2001–2010 年','比较受监管企业与对照企业在政策前后的能耗、产出和产值能效，判断节能是否伴随生产收缩，以及是否存在额外能效改善。构成 Table 1 与 Figure 3 的主要数据基础。'],['ASIF<br>工业企业调查','企业产值、行业、地址、所有制及财务信息','与股权网络匹配后，追踪关联企业是否扩大生产；对无股权关联企业，比较不同行业监管强度下的产出变化。企业特征还用于匹配对照组和回归控制。'],['CARD<br>工商注册数据','企业登记与股东持股信息，可追踪多层投资关系','识别受监管企业的子公司、被投资企业、股东及同一股东持有的企业，区分集团内关联企业与无股权关联的市场竞争者，建立生产转移分析所需的企业网络。'],['ATS<br>年度税收调查','补充产值与能源记录，部分年份含用电信息','与 CESD、ASIF 交叉核对产值和能源记录，并补充缺失能耗；用替代数据检验结果是否由漏报或数据异常驱动。用电信息还用于检查企业是否只是把其他能源换成电力。']])+'<p class="caption">能耗基准样本含 427 家受监管企业。CESD 的基准能源记录未完整覆盖电力，ASIF 未覆盖所有小微企业；数据覆盖限制会影响可纳入的企业与结果口径。</p>')
setbody(10,'<ul class="points"><li><b>关联类型：</b>子公司、被投资企业、股东，以及股东持有的其他企业。</li><li><b>持股门槛与追溯范围：</b>每层持股要求至少 25%，最多追溯两层投资关系。</li><li><b>排除范围：</b>仅通过国资管理机构形成的共同联系不计入关联网络。</li><li><b>主分析样本：</b>在关联网络中，选择与受监管企业处于同一四位行业的企业。四位行业是较细的行业分类，同类产品更可能承接转移的生产。</li><li><b>安慰剂样本：</b>选择同一二位行业、但不同四位行业的关联企业，观察产品相近程度较低时是否仍会扩张；它们仍具有股权关联身份。</li></ul>')
